#define main historical_main
#include "../chi2-cuda/chi2.cu"
#undef main
int main(){const int rows=12,cols=7,ncases=5,ncontrols=7;unsigned char input[rows*cols];float cpu[cols],got[cols];for(int r=0;r<rows;r++)for(int c=0;c<cols;c++)input[r*cols+c]='0'+(r*r+c*7+r*c)%3;cpu_kernel(rows,cols,ncases,ncontrols,input,cpu);unsigned char*d;float*out;cudaMalloc(&d,sizeof(input));cudaMalloc(&out,sizeof(got));cudaMemcpy(d,input,sizeof(input),cudaMemcpyHostToDevice);chi_kernel<<<1,32>>>(rows,cols,ncases,ncontrols,d,out);auto status=cudaDeviceSynchronize();cudaMemcpy(got,out,sizeof(got),cudaMemcpyDeviceToHost);double ma=0;int wrong=0;for(int c=0;c<cols;c++){printf("CHI2_REFERENCE_WITNESS column=%d native_gpu=%.9g original_cpu=%.9g\n",c,got[c],cpu[c]);ma=fmax(ma,fabs(double(got[c])-cpu[c]));wrong+=fabs(got[c]-cpu[c])>1e-4;}printf("CHI2_REFERENCE_SUMMARY status=%d checked=%d mismatches=%d max_abs_error=%.12g original_tolerance=1e-4\n",int(status),cols,wrong,ma);cudaFree(d);cudaFree(out);return status==cudaSuccess&&wrong>0?0:2;}
